/// Null on any failure → the legacy `sh -c <command>` delivery.
static Future<Directory?> _writeGuardedScript(String command) async {
  Directory dir;
  try {
    dir = await Directory.systemTemp.createTemp('fa_sh_cmd_');
  } on Object {
