  if (Platform.isWindows) {
    args = ['/c', command];
  } else if (scriptDir != null) {
    final scriptPath = '${scriptDir.path}/cmd.sh';
    args = ownSession
        ? ['sh', '-c', effectiveCommand, 'sh', scriptPath]
        : ['-c', effectiveCommand, 'sh', scriptPath];
  } else {
    args = ownSession ? ['sh', '-c', command] : ['-c', command];
  }
