}

static Future<(Result<Process, ExecutionError>, Directory?)> _start(
  String command,
  ShellExecOptions? options, {
  bool ownSession = false,
}) async {
  // gh-1763 AC1 (POSIX only; Windows `cmd /c` keeps the verbatim
