+        final jobs = ShellJobRegistry(env: env);
+        final tool = shellTool(env, jobs: jobs);
+        final result = await tool.execute(
+          {'command': 'pkill -f fa_self_match_tok_1763; echo survived'},
+          null,
+          null,
+        );
