import 'dart:io';
import 'package:flutter_agent_harness/io.dart';

Future<String?> resolve(String name) async {
  final r = await Process.run('sh', <String>['-c', 'command -v $name']);
  if (r.exitCode != 0) return null;
  final p = (r.stdout as String).trim();
  return p.isEmpty ? null : p;
}

Future<void> main() async {
  final pgrep = await resolve('pgrep');
  final pkill = await resolve('pkill');
  final killall = await resolve('killall');
  final out = Directory.systemTemp.createTempSync('fa_guard_probe_');
  File('${out.path}/prelude.sh').writeAsStringSync(bashGuardPrelude());
  if (pgrep != null && pkill != null) {
    File('${out.path}/pkill').writeAsStringSync(
      buildPkillShim(realPkill: pkill, realPgrep: pgrep),
    );
  }
  if (pgrep != null && killall != null) {
    File('${out.path}/killall').writeAsStringSync(
      buildKillallShim(realKillall: killall, realPgrep: pgrep),
    );
  }
  stdout.writeln(out.path);
  stdout.writeln('pgrep=$pgrep pkill=$pkill killall=$killall');
}
