  File pidFile,
  List<StreamSubscription<ProcessSignal>> signalSubs, {
  void Function(int code) exitProcess = exit,
}) =>
    () => unawaited(
      hubGracefulExit(hub, pidFile, signalSubs, exitProcess: exitProcess),

