      case "$fa_body" in
        [0-9]*|[Ss][Ii][Gg]*|[A-Z]*) continue ;;
      esac
      fa_rest="$fa_body"
      while [ -n "$fa_rest" ]; do
        fa_c="${fa_rest%"${fa_rest#?}"}"
